/* From Uiverse.io by NlghtM4re - Tags: green, card, code, menu */
.__UIV_SCOPE__ .container {
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .window {
  position: absolute;
  height: 200px;
  width: 300px;
  background-color: #fff;
  border: 2px solid #333;
  border-radius: 15px;
  overflow: hidden;
}

.__UIV_SCOPE__ .window-title {
  height: 30px;
  background-color: #333;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  box-shadow: 0px 2px 2px rgba(0, 0, 0, 0.25);
}

.__UIV_SCOPE__ .window-title p {
  color: #fff;
  font-weight: bold;
  margin: 0;
  padding: 0;
  text-align: left;
}

.__UIV_SCOPE__ .window-buttons {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .window-button {
  width: 10px;
  height: 10px;
  border-radius: 5px;
  margin: 5px;
  transition: background-color 0.2s ease;
}

.__UIV_SCOPE__ .window-button.close {
  background-color: #f00;
}

.__UIV_SCOPE__ .window-button.close:hover {
  background-color: rgb(182, 2, 2);
  cursor: pointer;
}

.__UIV_SCOPE__ .window-button.reduce {
  background-color: #ff0;
}

.__UIV_SCOPE__ .window-button.reduce:hover {
  background-color: rgb(172, 172, 4);
  cursor: pointer;
}

.__UIV_SCOPE__ .window-button.fullscreen {
  background-color: #0f0;
}

.__UIV_SCOPE__ .window-button.fullscreen:hover {
  background-color: rgb(7, 159, 7);
  cursor: pointer;
}

.__UIV_SCOPE__ .window-button:focus {
  outline: none;
}

.__UIV_SCOPE__ .console {
  width: 100%;
  height: calc(100% - 30px);
  background-color: #000;
  color: #fff;
  overflow: auto;
}

.__UIV_SCOPE__ .console pre {
  margin: 0;
  padding: 5px;
  font-size: 15px;
}

.__UIV_SCOPE__ .console pre code {
  color: #0f0;
  outline: none;
}

.__UIV_SCOPE__ .console::-webkit-scrollbar {
  width: 8px;
}

.__UIV_SCOPE__ .console::-webkit-scrollbar-track {
  background-color: #333;
}

.__UIV_SCOPE__ .console::-webkit-scrollbar-thumb {
  background-color: #666;
  border-radius: 10px;
  border: 2px solid #333;
}

.__UIV_SCOPE__ .console::-webkit-scrollbar-thumb:hover {
  background-color: #999;
}
